import os, json, shutil, stat, subprocess
root = "E:\\0zhongqi"
q = os.path.join(root, "_QUARANTINE_20261027")
exts = set([".py", ".ps1", ".sh", ".bat", ".cmd", ".js", ".ts", ".pl", ".rb", ".vbs"])
found = []
for dp, dn, fn in os.walk(root):
    if dp == q or dp.startswith(q + os.sep): continue
    if ".git" in dn: found.append([os.path.join(dp, ".git"), "DOTGIT-DIR"])
    for f in fn:
        if os.path.splitext(f)[1].lower() in exts:
            found.append([os.path.join(dp, f), os.path.getsize(os.path.join(dp, f))])
py1 = ""
try:
    with open(os.path.join(root, "ATTACH", "1.py"), "rb") as fh: pass
except Exception: pass
import glob
cands = glob.glob(os.path.join(root, "*", "1.py"))
if cands:
    try:
        with open(cands[0], "rb") as fh: py1 = fh.read().decode("utf-8", "replace")[:6000]
    except Exception as e: py1 = "READ-ERR " + repr(e)[:100]
deleted = []
for p, s in found:
    if s == "DOTGIT-DIR": continue
    try: os.remove(p); deleted.append(p)
    except Exception as e: deleted.append("FAIL " + p)
def ro(func, path, exc):
    try: os.chmod(path, stat.S_IWRITE); func(path)
    except Exception: pass
qmsg = ""
if os.path.isdir(q):
    try:
        shutil.rmtree("\\\\?\\" + q, onerror=ro)
        qmsg = "Q-DELETED" if not os.path.exists(q) else "Q-STILL-EXISTS"
    except Exception as e: qmsg = "Q-ERR " + repr(e)[:200]
else: qmsg = "Q-NOT-FOUND"
try:
    r = subprocess.run(["ssh", "-o", "BatchMode=yes", "-o", "StrictHostKeyChecking=accept-new", "-o", "ConnectTimeout=15", "BNI@100.84.137.117", "hostname & whoami"], capture_output=True, timeout=60)
    ssh = {"rc": r.returncode, "out": r.stdout.decode("ascii", "replace")[:500], "err": r.stderr.decode("ascii", "replace")[:500]}
except Exception as e:
    ssh = {"rc": -1, "out": "", "err": repr(e)[:300]}
final = sorted(os.listdir(root))
print(json.dumps({"found": found, "py1_head": py1[:1500], "deleted": deleted, "qmsg": qmsg, "ssh": ssh, "final": final}, ensure_ascii=True))
